import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import playwright from 'eslint-plugin-playwright';

export default tseslint.config(
  {
    ignores: [
      'node_modules/',
      'playwright-report/',
      'test-results/',
      'blob-report/',
      '.features-gen/', // generated by bddgen
      'cucumber-report/', // generated by the reporters
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.recommendedTypeChecked.map((c) => ({
    ...c,
    files: ['**/*.ts'],
  })),

  {
    files: ['**/*.ts'],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // Un-awaited Playwright calls are the most common cause of flaky tests
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/await-thenable': 'error',
      '@typescript-eslint/no-misused-promises': 'error',
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_' },
      ],
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { fixStyle: 'inline-type-imports' },
      ],
      'no-console': 'error', // use the shared winston logger instead
      eqeqeq: ['error', 'always'],
      'prefer-const': 'error',
    },
  },

  // Playwright rules for step definitions (the assertions live here). The
  // test()-block rules (expect-expect, valid-title...) do not apply because
  // steps are not inside test(); the scenarios are in the .feature files.
  {
    ...playwright.configs['flat/recommended'],
    files: ['step-definitions/**/*.ts'],
    rules: {
      ...playwright.configs['flat/recommended'].rules,
      'playwright/no-wait-for-timeout': 'error',
      'playwright/no-force-option': 'error',
      'playwright/prefer-web-first-assertions': 'error',
      'playwright/missing-playwright-await': 'error',
      // Steps run inside the generated test(), not inside one here
      'playwright/no-standalone-expect': 'off',
    },
  },

  // Page objects must not contain assertions
  {
    files: ['pages/**/*.ts'],
    rules: {
      'no-restricted-syntax': [
        'error',
        {
          selector: "CallExpression[callee.name='expect']",
          message: 'Keep assertions in step definitions, not page objects.',
        },
      ],
    },
  },
);
